    if (!proposal || !action?.requiresDraft) return { ok: true, value: project(saved.value, this.options.mode, [], warnings) };
    let draft: Awaited<ReturnType<DraftGenerator['generate']>>;
    try { draft = await this.options.draftGenerator.generate({ caseSnapshot: saved.value, proposal, agentProfile: config.agentProfile, policyDecision: evaluated.value.decision }); }
    catch { draft = failure('DRAFT_GENERATION_FAILED', 'No se pudo generar el borrador'); }
    if (!draft.ok) return { ok: true, value: project(saved.value, this.options.mode, [draft.error], warnings) };
    if (!sameRef(bundleRef(config), bundleRef(this.options.getConfig()))) return failure('STALE_PROPOSAL', 'La configuración ha cambiado; vuelve a evaluar');
    if (!DraftSchema.safeParse(draft.value).success || draft.value.proposalId !== proposal.proposalId || draft.value.status !== 'generated' || draft.value.aiMode !== this.options.mode) return { ok: true, value: project(saved.value, this.options.mode, [{ code: 'DRAFT_GENERATION_FAILED', message: 'Borrador inválido', retryable: false }], warnings) };
    const final: CaseSnapshot = { ...saved.value, revision: saved.value.revision + 1, drafts: [...saved.value.drafts, draft.value], status: 'READY_TO_REPLY' };
    const result = await this.options.repository.saveIfRevision(final, saved.value.revision);
    return result.ok ? { ok: true, value: project(result.value, this.options.mode, [], warnings) } : result;
  }
}
import type { CaseSnapshot, ConfigBundle, DecisionRecord, Result } from '../../contracts';
import { reconcileFacts } from '../../domain/facts';
import { evaluatePolicy } from '../../domain/policies/evaluate-policy';
import { evaluateWorkflow } from '../../domain/workflows/evaluate-workflow';
import { planAction } from '../../domain/actions/plan-action';
import { bundleRef } from './helpers';

export function evaluate(snapshot: CaseSnapshot, config: ConfigBundle, eventId: string, mode: 'replay' | 'openai'): Result<{ snapshot: CaseSnapshot; decision: ReturnType<typeof evaluatePolicy> }> {
  const facts = reconcileFacts({ assertions: snapshot.assertions, messages: snapshot.messages, factSchema: config.factSchema });
  if (!facts.ok) return facts;
  const context = { knowledge: facts.value, events: snapshot.events, blockers: snapshot.blockers, policyOptions: config.businessPolicy.advisoryCall };
  const decision = evaluatePolicy({ ...context, policy: config.businessPolicy, actionCatalog: config.actionCatalog });
  // The current action can be WAIT after agreement while the prior orientation
  // remains satisfied. Re-evaluate that orientation against current facts and
  // protections; never infer readiness solely from the confirmation event.
  const priorReady = config.workflow.milestones.some(m => m.terminalRoute && m.prerequisites.length > 0 && m.prerequisites.every(id => snapshot.workflowProgress.milestones.some(previous => previous.milestoneId === id && previous.status === 'completed')));
  const orientation = decision.result === 'WAIT' && decision.ruleIds.includes('R08') && priorReady
    ? evaluatePolicy({ ...context, events: context.events.filter(e => !['CUSTOMER_CONFIRMED_NEXT_STEP', 'HUMAN_HANDOFF_CONFIRMED', 'DRAFT_APPROVED', 'DRAFT_EDITED', 'DRAFT_DISCARDED', 'MESSAGE_SIMULATED_AS_SENT'].includes(e.type)), policy: config.businessPolicy, actionCatalog: config.actionCatalog })
    : decision;
  const workflow = evaluateWorkflow({ ...context, policyDecision: orientation, definition: config.workflow });
  const ref = bundleRef(config);
  const revision = snapshot.revision + 1;
  const proposal = planAction({ decision, catalog: config.actionCatalog, profile: config.agentProfile, proposalId: `proposal-${eventId}`, caseRevision: revision, configBundleRef: ref });
  if (!proposal.ok) return proposal;
  const record: DecisionRecord = { decisionId: `decision-${eventId}`, inputEventIds: [eventId], beforeRevision: snapshot.revision, afterRevision: revision, factAssertionIds: snapshot.assertions.map(a => a.assertionId), evidenceRefs: decision.evidenceRefs, ruleIds: decision.ruleIds, configBundleRef: ref, aiMode: mode, outcome: decision.result, warnings: [] };
  const terminalCompleted = config.workflow.milestones.some(m => m.terminalRoute && workflow.milestones.some(result => result.milestoneId === m.id && result.status === 'completed'));
  const status: CaseSnapshot['status'] = decision.result === 'STOP_CONTACT' ? 'DO_NOT_CONTACT' : terminalCompleted ? 'NEXT_STEP_AGREED' : decision.result === 'HUMAN_REVIEW_REQUIRED' ? 'ON_HOLD_REVIEW' : decision.result === 'WAIT' ? 'WAITING_CUSTOMER' : 'NEEDS_ADVISOR';
  return { ok: true, value: { snapshot: { ...snapshot, revision, assertions: snapshot.assertions, knowledge: facts.value, workflowProgress: workflow, proposals: [...snapshot.proposals.map(p => ({ ...p, status: 'superseded' as const })), proposal.value], decisions: [...snapshot.decisions, record], configBundleRef: ref, status, analysisStatus: 'complete' }, decision } };
}

import { InterpretationSchema, type Interpretation, type Interpreter, type DraftGenerator, type Result, type ApplicationError } from '../../contracts';

type InterpretInput = Parameters<Interpreter['interpret']>[0];
export const failure = (code: ApplicationError['code'], message: string, retryable = false): Result<never> => ({ ok: false, error: { code, message, retryable } });

/** Model-produced claims have customer-message authority only; references must identify actual text. */
export function validateInterpretation(value: unknown, input: InterpretInput): Result<Interpretation> {
  const parsed = InterpretationSchema.safeParse(value);
  if (!parsed.success) return failure('MODEL_OUTPUT_INVALID', 'La salida del modelo no tiene el formato esperado');
  const ids = new Set<string>();
  for (const a of parsed.data.assertions) {
    if (a.source !== 'customer_message' || a.reviewStatus !== 'unreviewed' || ids.has(a.assertionId)) return failure('MODEL_OUTPUT_INVALID', 'La salida incluye autoridad o identificadores inválidos');
    ids.add(a.assertionId);
    const field = input.factSchema.fields.find(f => f.id === a.fieldId);
    if (!field || field.schemaVersion !== a.schemaVersion || !field.scopes.includes(a.subjectRef.scope) || (a.unit && !field.units.includes(a.unit))) return failure('MODEL_OUTPUT_INVALID', 'La salida contiene un campo no válido');
    if (a.value === undefined && a.precision !== 'ambiguous') return failure('MODEL_OUTPUT_INVALID', 'La salida omite un valor requerido');
    if (a.value !== undefined) {
      const v = a.value;
      const range = typeof v === 'object' && !Array.isArray(v);
      const valid = field.type === 'money' || field.type === 'range' ? typeof v === 'number' || range : field.type === 'number' ? typeof v === 'number' : field.type === 'boolean' ? typeof v === 'boolean' : field.type === 'collection' ? Array.isArray(v) : typeof v === 'string';
      if (!valid || (field.type === 'enum' && (typeof v !== 'string' || !field.enumOptions.includes(v)))) return failure('MODEL_OUTPUT_INVALID', 'La salida contiene un valor no válido');
      const numbers = typeof v === 'number' ? [v] : range ? [v.min, v.max] : [];
      const c = field.structuralValidation;
      if (numbers.some(n => (c?.min !== undefined && n < c.min) || (c?.max !== undefined && n > c.max) || (c?.integer && !Number.isInteger(n)))) return failure('MODEL_OUTPUT_INVALID', 'La salida contiene un valor fuera del esquema');
    }
    for (const ref of a.evidenceRefs) {
      const message = input.messages.find(m => m.messageId === ref.messageId);
      if (!message || message.role !== 'customer' || message.content.type !== 'text') return failure('EVIDENCE_INVALID', 'La evidencia no corresponde a texto del cliente');
      if (!message.content.text.includes(a.rawValue)) return failure('EVIDENCE_INVALID', 'El valor declarado no coincide con la evidencia');
      if ((ref.quote && !message.content.text.includes(ref.quote)) || (ref.end !== undefined && (ref.end > message.content.text.length || (ref.quote !== undefined && message.content.text.slice(ref.start, ref.end) !== ref.quote)))) return failure('EVIDENCE_INVALID', 'El fragmento de evidencia no coincide');
    }
  }
  for (const blocker of parsed.data.blockers) {
    if (blocker.status !== 'open') return failure('MODEL_OUTPUT_INVALID', 'El modelo no puede cerrar avisos');
    if (!blocker.evidenceRefs.length || blocker.evidenceRefs.some(ref => { const m = input.messages.find(x => x.messageId === ref.messageId); return !m || m.role !== 'customer' || m.content.type !== 'text' || (ref.quote && !m.content.text.includes(ref.quote)) || (ref.end !== undefined && (ref.end > m.content.text.length || (ref.quote !== undefined && m.content.text.slice(ref.start, ref.end) !== ref.quote))); })) return failure('EVIDENCE_INVALID', 'La evidencia del aviso no es válida');
  }
  return { ok: true, value: parsed.data };
}

export function validateDraftRequest(input: Parameters<DraftGenerator['generate']>[0]): Result<true> {
  const { proposal, caseSnapshot, policyDecision } = input;
  if (proposal.status !== 'active' || proposal.originCaseRevision !== caseSnapshot.revision || JSON.stringify(proposal.configBundleRef) !== JSON.stringify(caseSnapshot.configBundleRef)) return failure('STALE_PROPOSAL', 'La propuesta debe reevaluarse');
  if (!policyDecision.allowedActions.includes(proposal.actionType) || policyDecision.prohibitedActions.includes(proposal.actionType)) return failure('POLICY_DENIED', 'La acción no está permitida');
  return { ok: true, value: true };
}
